import { Filters } from "@axeth/core"
import { denoPlugins } from "jsr:@luca/esbuild-deno-loader@0.11.1";
import type { Manifest } from "./types/Manifest.ts";
import { parseArgs } from "./utils/parseArgs.ts";
import esbuild from "npm:esbuild@0.27.2";
import chalk from "npm:chalk@5.6.2";
import path from "node:path";

const [settings] = parseArgs(Deno.args);
const configPath = path.resolve("./deno.json");

class TSBuilds extends Filters {
  private typescript = "ts";
  private bpPath = `${this.basePath}/BP`;

  override async apply(): Promise<void> {
    const manifest = await this.readManifest(this.bpPath);
    if (!manifest) return;
    const entryPath = manifest.modules.find((x) => x.entry)?.entry;
    if (!entryPath) return;

    const scriptPath = "./packs" + "/" + entryPath.replace(".js", `.${this.typescript}`);

    await this.runLinter()
    await this.runBuildLib();
    await this.runBuildScripts(scriptPath, entryPath);
  }

  private async runBuildScripts(scriptPath: string, entryPath: string) {
    await esbuild.build({
      plugins: [
        {
          name: "alias-axeth-api",
          setup(build) {
            build.onResolve({ filter: /^@axeth\/api$/ }, () => {
              return { path: "./AxethLib.js", external: true };
            });
          },
        },
      ],
      bundle: true,
      entryPoints: [
        scriptPath,
      ],
      external: [
        "@minecraft/server",
        "@minecraft/server-ui",
      ],
      format: "esm",
      outfile: this.bpPath + "/" + entryPath,
      sourcemap: true,
      ...settings,
    })
    this.msg(`Successfully built script: ${chalk.green("BP/" + entryPath)}`);
    return;
  }

  private async runBuildLib() {
    await esbuild.build({
      bundle: true,
      entryPoints: ["jsr:@axeth/api"],
      external: [
        "@minecraft/server",
        "@minecraft/server-ui",
      ],
      format: "esm",
      outfile: this.bpPath + "/scripts/AxethLib.js",
      minify: true,
      keepNames: false,
      sourcemap: true,
      plugins: denoPlugins({ configPath: configPath }) as esbuild.Plugin[],
      ...settings,
    })
    this.msg(`Successfully built library: ${chalk.green("BP/scripts/AxethLib.js")}`);
    return;
  }

  private async runLinter(): Promise<boolean> {
    return await new Promise((resolve) => {
      const run = async () => {
        const lintProcess = new Deno.Command("deno", {
          args: ["lint", "./packs"],
          stdout: "null",
          stderr: "null",
        }).spawn();
        const lintStatus = await lintProcess.status;
        if (!lintStatus.success) {
          this.msg(`Linting failed`);
          resolve(false);
        } else {
          this.msg(`Linting passed ${chalk.blue("./scripts")}`);
          resolve(true);
        }
      };
      run();
    });
  }

  public async readManifest(bpPath: string): Promise<Manifest | null> {
    try {
      return JSON.parse(
        await Deno.readTextFile(`${bpPath}/manifest.json`),
      ) as Manifest;
    } catch {
      return null;
    }
  }
}

export { TSBuilds };

